    """Precompute lucky numbers up to a limit"""
    lucky = []
    q = ['4', '7']
    while q:
        current = q.pop(0)
        if int(current) <= limit:
            lucky.append(int(current))
            if len(current) < 7:  # Avoid overflow since 7777777 > 100000
