def solve(n, a):
    # Compute prefix alternating sum: p[i] = a[0] - a[1] + a[2] - ... + (-1)^i * a[i]
    prefix = [0] * n
    prefix[0] = a[0]
    for i in range(1, n):
        prefix[i] = prefix[i-1] + (a[i] if i % 2 == 0 else -a[i])

    def check(p):
        # All prefix sums must be non-negative
        for x in p:
            if x < 0:
                return False
        # Last prefix sum must be 0
        return p[n-1] == 0

    # Check without any swap
    if check(prefix):
        return True

    # Try swapping each adjacent pair
    for i in range(n-1):
        # When swapping a[i] and a[i+1]:
        # For j >= i, prefix sum changes by delta
        # delta = 2 * (-1)^i * (a[i+1] - a[i])
        if i % 2 == 0:
            delta = 2 * (a[i+1] - a[i])
