        inv[MAX_N-1] = pow_mod(fact[MAX_N-1], MOD - 2)
        for i in range(MAX_N-2, -1, -1):
            inv[i] = (inv[i+1] * (i+1)) % MOD

        def nCr(n_r, r):
            if r < 0 or r > n_r:
                return 0
            return fact[n_r] * inv[r] % MOD * inv[n_r - r] % MOD
    else:
        def nCr(n_r, r):
            if r < 0 or r > n_r:
                return 0
            num = 1
            for i in range(r):
                num = (num * ((n_r - i) % MOD)) % MOD
            denom = 1
            for i in range(1, r + 1):
                denom = (denom * i) % MOD
            return num * pow_mod(denom, MOD - 2) % MOD

    # Calculate answer using the formula: sum of i^k * C(n-1, i-1)
    result = 0
    if n - 1 >= 0:
        for i in range(1, n):
            term = (pow_mod(i, k) * nCr(n - 1, i - 1)) % MOD
            result = (result + term) % MOD

    return '\n' + str(result) + '\n'

